-- reviewed: PLAT-10 item B, 2026-11-01. Generated by drizzle-kit from
-- src/modules/kernel/schema/roles.ts; this header, the grants and the seed at the end added by hand.
--
-- core_roles (data §2.1; identity and tenancy §2; PLAT-10 plan 2.3): the role bundles. A platform
-- table, exempt from tenancy (data §2.4, test/schema/exemptions.ts): no account_id, no policies.
-- The runtime roles may only read it: the default privileges of 0001 gave elx_app and
-- elx_platform SELECT, INSERT, UPDATE and DELETE, so the three writes are revoked from both. The
-- API loads the table once at boot through the platform pool (PermissionResolver).
--
-- The seed is docs/contracts/roles.yaml, row for row (the eleven system roles of README §11);
-- apps/api/test/roles-seed.test.ts fails when the two differ. ON CONFLICT re-seeds a system role,
-- so a later migration that changes a bundle repeats this statement with the new lists; a custom
-- role (custom = true, a later order) is never overwritten.
CREATE TABLE "core_roles" (
	"key" text PRIMARY KEY NOT NULL,
	"scope" text NOT NULL,
	"surface" text NOT NULL,
	"site_scoped" boolean NOT NULL,
	"permissions" text[] NOT NULL,
	"custom" boolean DEFAULT false NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "core_roles_scope_check" CHECK ("core_roles"."scope" IN ('account', 'platform')),
	CONSTRAINT "core_roles_surface_check" CHECK ("core_roles"."surface" IN ('staff', 'driver', 'platform'))
);
